import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { addStoreCreditsToCartWorkflow } from "@medusajs/loyalty-plugin/workflows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await addStoreCreditsToCartWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
        amount: 50,
      },
    })

  res.send(result)
}

